What does this print?

```typescript
class Temperature {
  constructor(public celsius: number) {}
  get fahrenheit(): number {
    return this.celsius * 9 / 5 + 32;
  }
}
class Reading extends Temperature {
  override get fahrenheit(): number {
    return Math.round(super.fahrenheit);
  }
}
const r = new Reading(21.7);
console.log(r.fahrenheit, r instanceof Temperature, Object.keys(r).join(","));
export {};
```

